import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_layernorm_forward(torch::Tensor x,
                                      torch::Tensor weight,
                                      torch::Tensor bias,
                                      double eps);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__inline__ __device__ double warpReduceSum(double val) {
  #pragma unroll
  for (int offset = 16; offset > 0; offset >>= 1) {
    val += __shfl_down_sync(0xffffffff, val, offset);
  }
  return val;
}

__inline__ __device__ double blockReduceSum(double val) {
  __shared__ double shared[32];
  int lane = threadIdx.x % warpSize;
  int wid  = threadIdx.x / warpSize;

  val = warpReduceSum(val);
  if (lane == 0) shared[wid] = val;
  __syncthreads();

  int numWarps = (blockDim.x + warpSize - 1) / warpSize;
  val = (threadIdx.x < numWarps) ? shared[lane] : 0.0;
  if (wid == 0) val = warpReduceSum(val);
  return val;
}
__inline__ __device__ void blockReduceSum2(double val1, double val2, double &out1, double &out2) {
  __shared__ double shared1[32];
  __shared__ double shared2[32];
  int lane = threadIdx.x % warpSize;
  int wid  = threadIdx.x / warpSize;
  val1 = warpReduceSum(val1);
  val2 = warpReduceSum(val2);
  if (lane == 0) {
    shared1[wid] = val1;
    shared2[wid] = val2;
  }
  __syncthreads();
  int numWarps = (blockDim.x + warpSize - 1) / warpSize;
  val1 = (threadIdx.x < numWarps) ? shared1[lane] : 0.0;
  val2 = (threadIdx.x < numWarps) ? shared2[lane] : 0.0;
  if (wid == 0) {
    val1 = warpReduceSum(val1);
    val2 = warpReduceSum(val2);
  }
  out1 = val1;
  out2 = val2;
}

template <typename T>
__global__ void layernorm_reduce_kernel(
    const T* __restrict__ X,
    double* __restrict__ sumBuf,
    double* __restrict__ sumsqBuf,
    int64_t N, int64_t M, int64_t chunkSize, int64_t numChunks)
{
  int64_t n = blockIdx.x;
  int64_t c = blockIdx.y;
  int tid = threadIdx.x;
  int nthreads = blockDim.x;
  int64_t start = c * chunkSize;
  int64_t end = start + chunkSize;
  if (end > M) end = M;
  if (start >= end) {
    if (tid == 0) {
      sumBuf[n * numChunks + c] = 0.0;
      sumsqBuf[n * numChunks + c] = 0.0;
    }
    return;
  }
  const T* Xrow = X + n * M;
  int64_t len = end - start;
  int64_t len4 = len / 4;
  int64_t tail = len4 * 4;
  const float4* X4 = reinterpret_cast<const float4*>(Xrow + start);
  double sum = 0.0;
  double sumsq = 0.0;
  #pragma unroll 4
  for (int64_t i = tid; i < len4; i += nthreads) {
    float4 v4 = __ldg(&X4[i]);
    double vx = static_cast<double>(v4.x);
    double vy = static_cast<double>(v4.y);
    double vz = static_cast<double>(v4.z);
    double vw = static_cast<double>(v4.w);
    sum += vx + vy + vz + vw;
    sumsq += vx * vx + vy * vy + vz * vz + vw * vw;
  }
  #pragma unroll 4
  for (int64_t i = tail + tid; i < len; i += nthreads) {
    double v = static_cast<double>(__ldg(&Xrow[start + i]));
    sum += v;
    sumsq += v * v;
  }
  double total_sum, total_sumsq;
  blockReduceSum2(sum, sumsq, total_sum, total_sumsq);
  if (tid == 0) {
    sumBuf[n * numChunks + c] = total_sum;
    sumsqBuf[n * numChunks + c] = total_sumsq;
  }
}
__global__ void layernorm_finalize_kernel(
    const double* __restrict__ sumBuf,
    const double* __restrict__ sumsqBuf,
    double* __restrict__ meanBuf,
    double* __restrict__ invStdBuf,
    int64_t N, int64_t M, int64_t numChunks, double eps)
{
  int64_t n = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  if (n >= N) return;
  const double* srow = sumBuf + n * numChunks;
  const double* sqrow = sumsqBuf + n * numChunks;
  double sum = 0.0;
  double sumsq = 0.0;
  for (int64_t c = 0; c < numChunks; ++c) {
    sum += srow[c];
    sumsq += sqrow[c];
  }
  double mean = sum / (double)M;
  double var = sumsq / (double)M - mean * mean;
  if (var < 0.0) var = 0.0;
  double inv_std = rsqrt(var + eps);
  meanBuf[n] = mean;
  invStdBuf[n] = inv_std;
}
template <typename T, int GROUP_N>
__global__ void layernorm_normalize_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    const double* __restrict__ meanBuf,
    const double* __restrict__ invStdBuf,
    int64_t N, int64_t M, int64_t chunkSize)
{
  int64_t n0 = (int64_t)blockIdx.x * GROUP_N;
  int64_t c = blockIdx.y;
  int tid = threadIdx.x;
  int nthreads = blockDim.x;
  int64_t start = c * chunkSize;
  int64_t end = start + chunkSize;
  if (end > M) end = M;
  if (start >= end) return;
  int64_t len = end - start;
  int64_t len4 = len / 4;
  int64_t tail = len4 * 4;
  int groupCount = 0;
  int64_t ns[GROUP_N];
  double means[GROUP_N];
  double invStds[GROUP_N];
  #pragma unroll
  for (int r = 0; r < GROUP_N; ++r) {
    int64_t n = n0 + r;
    if (n < N) {
      ns[groupCount] = n;
      means[groupCount] = meanBuf[n];
      invStds[groupCount] = invStdBuf[n];
      groupCount++;
    }
  }
  if (groupCount == 0) return;
  extern __shared__ unsigned char smem_raw[];
  float4* Wsh = reinterpret_cast<float4*>(smem_raw);
  float4* Bsh = Wsh + nthreads;
  const float4* W4 = reinterpret_cast<const float4*>(W + start);
  const float4* B4 = reinterpret_cast<const float4*>(B + start);
  for (int64_t tileStart = 0; tileStart < len4; tileStart += nthreads) {
    int64_t idx4 = tileStart + tid;
    bool valid = idx4 < len4;
    if (valid) {
      Wsh[tid] = __ldg(&W4[idx4]);
      Bsh[tid] = __ldg(&B4[idx4]);
    }
    __syncthreads();
    if (valid) {
      float4 w4 = Wsh[tid];
      float4 b4 = Bsh[tid];
      #pragma unroll
      for (int r = 0; r < GROUP_N; ++r) {
        if (r >= groupCount) break;
        int64_t n = ns[r];
        double mean = means[r];
        double inv_std = invStds[r];
        const T* Xrow = X + n * M;
        T* Yrow = Y + n * M;
        const float4* X4 = reinterpret_cast<const float4*>(Xrow + start);
        float4* Y4 = reinterpret_cast<float4*>(Yrow + start);
        float4 v4 = __ldg(&X4[idx4]);
        float4 out4;
        out4.x = static_cast<T>((static_cast<double>(v4.x) - mean) * inv_std * static_cast<double>(w4.x) + static_cast<double>(b4.x));
        out4.y = static_cast<T>((static_cast<double>(v4.y) - mean) * inv_std * static_cast<double>(w4.y) + static_cast<double>(b4.y));
        out4.z = static_cast<T>((static_cast<double>(v4.z) - mean) * inv_std * static_cast<double>(w4.z) + static_cast<double>(b4.z));
        out4.w = static_cast<T>((static_cast<double>(v4.w) - mean) * inv_std * static_cast<double>(w4.w) + static_cast<double>(b4.w));
        Y4[idx4] = out4;
      }
    }
    __syncthreads();
  }
  for (int64_t i = tail + tid; i < len; i += nthreads) {
    int64_t idx = start + i;
    double w = static_cast<double>(__ldg(&W[idx]));
    double b = static_cast<double>(__ldg(&B[idx]));
    #pragma unroll
    for (int r = 0; r < GROUP_N; ++r) {
      if (r >= groupCount) break;
      int64_t n = ns[r];
      double mean = means[r];
      double inv_std = invStds[r];
      const T* Xrow = X + n * M;
      T* Yrow = Y + n * M;
      double v = static_cast<double>(__ldg(&Xrow[idx]));
      double norm = (v - mean) * inv_std;
      Yrow[idx] = static_cast<T>(norm * w + b);
    }
  }
}
torch::Tensor cute_layernorm_forward(torch::Tensor x,
                                      torch::Tensor weight,
                                      torch::Tensor bias,
                                      double eps) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
  TORCH_CHECK(bias.is_cuda(), "bias must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
  TORCH_CHECK(bias.scalar_type() == at::kFloat, "bias must be float32");
  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();
  auto b_c = bias.contiguous();
  int64_t normalized_numel = w_c.numel();
  TORCH_CHECK(b_c.numel() == normalized_numel, "weight and bias must have same numel");
  TORCH_CHECK(x_c.numel() % normalized_numel == 0, "x numel must be divisible by normalized_shape numel");
  int64_t N = x_c.numel() / normalized_numel;
  int64_t M = normalized_numel;
  auto y = torch::empty_like(x_c);
  int threads = 512;
  // Determine number of chunks per row so that many CTAs can cooperate on
  // reducing/normalizing a single (potentially huge) row, improving SM
  // utilization when N (batch of rows) is small but M (row length) is huge.
  int64_t minElemPerChunk = (int64_t)threads * 4;
  int64_t maxChunks = (M + minElemPerChunk - 1) / minElemPerChunk;
  int64_t chunksPerRow64 = maxChunks < 64 ? maxChunks : 64;
  if (chunksPerRow64 < 1) chunksPerRow64 = 1;
  int chunksPerRow = (int)chunksPerRow64;
  int64_t chunkSize = (M + chunksPerRow - 1) / chunksPerRow;
  // align chunkSize to a multiple of 4 elements so float4 vector loads
  // starting at c * chunkSize remain 16-byte aligned.
  chunkSize = ((chunkSize + 3) / 4) * 4;
  if (chunkSize < 4) chunkSize = 4;
  int actualChunks = (int)((M + chunkSize - 1) / chunkSize);
  if (actualChunks < 1) actualChunks = 1;
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  auto options_d = x_c.options().dtype(at::kDouble);
  // Use per-chunk partial-sum buffers instead of atomics to avoid atomic
  // contention on the (small) N accumulators when many chunk-blocks
  // cooperate on the same row.
  auto sumBuf = torch::empty({N, (int64_t)actualChunks}, options_d);
  auto sumsqBuf = torch::empty({N, (int64_t)actualChunks}, options_d);
  auto meanBuf = torch::empty({N}, options_d);
  auto invStdBuf = torch::empty({N}, options_d);
  dim3 block(threads);
  dim3 grid_reduce((unsigned)N, (unsigned)actualChunks);
  layernorm_reduce_kernel<float><<<grid_reduce, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      sumBuf.data_ptr<double>(),
      sumsqBuf.data_ptr<double>(),
      N, M, chunkSize, (int64_t)actualChunks
  );
  int fin_threads = 128;
  int fin_blocks = (int)((N + fin_threads - 1) / fin_threads);
  layernorm_finalize_kernel<<<fin_blocks, fin_threads, 0, stream>>>(
      sumBuf.data_ptr<double>(),
      sumsqBuf.data_ptr<double>(),
      meanBuf.data_ptr<double>(),
      invStdBuf.data_ptr<double>(),
      N, M, (int64_t)actualChunks, eps
  );
  constexpr int GROUP_N = 4;
  dim3 grid_norm((unsigned)((N + GROUP_N - 1) / GROUP_N), (unsigned)actualChunks);
  size_t norm_smem_bytes = (size_t)threads * sizeof(float4) * 2;
  layernorm_normalize_kernel<float, GROUP_N><<<grid_norm, block, norm_smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_c.data_ptr<float>(),
      y.data_ptr<float>(),
      meanBuf.data_ptr<double>(),
      invStdBuf.data_ptr<double>(),
      N, M, chunkSize
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "layernorm_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

cute_layernorm_ext = load_inline(
    name="cute_layernorm_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["cute_layernorm_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include", "/root/cutegen_test/cutegen/cutlass/include/cute/"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Layer Normalization implemented with a single custom CUDA kernel using CuTe.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        if isinstance(normalized_shape, int):
            normalized_shape = (normalized_shape,)
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5

        self.weight = nn.Parameter(torch.ones(*self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(*self.normalized_shape))

        self._ext = cute_layernorm_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_layernorm_forward(x, self.weight, self.bias, self.eps)

